import fs from 'fs'
import path from 'path'

const OUT = path.join(process.cwd(), 'src/certifications/ai-102/cards')

function c(id, domain, task, tags, question, options, correctAnswers, explanation) {
  return { id, domain, task, tags: ['ai-102', ...tags], question, options, correctAnswers, explanation }
}

function writeDomain(exportName, filename, cards) {
  const lines = cards.map((card) => {
    const opts = card.options.map((o) => `      '${o.replace(/'/g, "\\'")}',`).join('\n')
    const tags = card.tags.map((t) => `'${t}'`).join(', ')
    const ca = card.correctAnswers.join(', ')
    return `  {
    id: '${card.id}',
    domain: '${card.domain}',
    task: '${card.task}',
    tags: [${tags}],
    question: '${card.question.replace(/'/g, "\\'")}',
    options: [
${opts}
    ],
    correctAnswers: [${ca}],
    explanation: '${card.explanation.replace(/'/g, "\\'")}',
  }`
  })
  const content = `import type { Card } from '../../../core/types'

export const ${exportName}: Card[] = [
${lines.join(',\n')}
]
`
  fs.mkdirSync(OUT, { recursive: true })
  fs.writeFileSync(path.join(OUT, filename), content)
  console.log(`Wrote ${filename}: ${cards.length} cards`)
}

